-- Source: FAA Data Portal (data.faa.gov) (4 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-18 verification): trivial -- one "FAA Data Portal" nav-link row
-- appears twice, byte-identical, single load run (1 distinct _SOURCE_RUN_ID).
-- Same crawl-boilerplate class as the CAPMAS/USCIS portal crawls, immaterial at
-- n=4 but fixed for consistency. Live: 4 rows / 3 distinct. Also independently
-- flagged in outputs/dedup_fix_batches/fixbatch_02.json from a prior sweep.
with source as (
    select * from {{ source('ripple_raw', 'FED_FAA_DATA_PORTAL') }}
    qualify row_number() over (
        partition by DATASET_NAME, DATASET_ID, CATEGORY, DESCRIPTION, ACCESS_URL,
                     FORMAT, UPDATE_FREQUENCY, LAST_UPDATED, GEOGRAPHIC_SCOPE,
                     TEMPORAL_COVERAGE, FIPS, N_NUMBER, AIRPORT_ID, LAT, LON
        order by _INGESTED_AT) = 1
)

select
    DATASET_NAME as dataset_name,
    DATASET_ID as dataset_id,
    CATEGORY as category,
    DESCRIPTION as description,
    ACCESS_URL as access_url,
    FORMAT as format,
    UPDATE_FREQUENCY as update_frequency,
    try_to_date(LAST_UPDATED) as last_updated,
    GEOGRAPHIC_SCOPE as geographic_scope,
    TEMPORAL_COVERAGE as temporal_coverage,
    FIPS as fips,
    N_NUMBER as n_number,
    AIRPORT_ID as airport_id,
    try_to_double(LAT) as lat,
    try_to_double(LON) as lon
from source
